-- # KEY_COLUMN_USAGE_S is KEY_COLUMN_USAGE, with shorter column names.
CREATE TABLE parent (id INT PRIMARY KEY);
CREATE TABLE child (parent_id INT REFERENCES parent);
SELECT * FROM information_schema.key_column_usage_s;
-- msg: CREATE TABLE 1
-- msg: CREATE TABLE 1
-- CONSTRAINT_CATALOG: :memory: CONSTRAINT_SCHEMA: PUBLIC CONSTRAINT_NAME: CHILD_FOREIGN_KEY_1 TABLE_CATALOG: :memory: TABLE_SCHEMA: PUBLIC TABLE_NAME: CHILD COLUMN_NAME: PARENT_ID ORDINAL_POSITION: 1 POSITION_IN_UC: 1
-- CONSTRAINT_CATALOG: :memory: CONSTRAINT_SCHEMA: PUBLIC CONSTRAINT_NAME: PARENT_PRIMARY_KEY TABLE_CATALOG: :memory: TABLE_SCHEMA: PUBLIC TABLE_NAME: PARENT COLUMN_NAME: ID ORDINAL_POSITION: 1 POSITION_IN_UC: NULL

-- # REF_CONSTRAINTS is REFERENTIAL_CONSTRAINTS, with shorter column names.
CREATE TABLE parent (id INT PRIMARY KEY);
CREATE TABLE child (parent_id INT REFERENCES parent);
SELECT * FROM information_schema.ref_constraints;
-- msg: CREATE TABLE 1
-- msg: CREATE TABLE 1
-- CONSTRAINT_CATALOG: :memory: CONSTRAINT_SCHEMA: PUBLIC CONSTRAINT_NAME: CHILD_FOREIGN_KEY_1 UNIQUE_CONSTR_CAT: :memory: UNIQUE_CONSTR_SCH: PUBLIC UNIQUE_CONSTR_NAME: PARENT_PRIMARY_KEY MATCH_OPTION: NONE UPDATE_RULE: NO ACTION DELETE_RULE: NO ACTION

-- # Each short name view has the same columns as its view, in the same order.
-- # These are the ones with a shorter name.
SELECT s.table_name, s.column_name, l.column_name
FROM information_schema.columns AS s
JOIN information_schema.columns AS l ON l.ordinal_position = s.ordinal_position AND l.table_name = CASE s.table_name WHEN 'TABLES_S' THEN 'TABLES' WHEN 'COLUMNS_S' THEN 'COLUMNS' WHEN 'KEY_COLUMN_USAGE_S' THEN 'KEY_COLUMN_USAGE' WHEN 'REF_CONSTRAINTS' THEN 'REFERENTIAL_CONSTRAINTS' END
WHERE s.column_name <> l.column_name;
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: CHAR_MAX_LENGTH COLUMN_NAME: CHARACTER_MAXIMUM_LENGTH
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: CHAR_OCTET_LENGTH COLUMN_NAME: CHARACTER_OCTET_LENGTH
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: NUMERIC_PREC_RADIX COLUMN_NAME: NUMERIC_PRECISION_RADIX
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: CHAR_SET_CATALOG COLUMN_NAME: CHARACTER_SET_CATALOG
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: CHAR_SET_SCHEMA COLUMN_NAME: CHARACTER_SET_SCHEMA
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: MAX_CARDINALITY COLUMN_NAME: MAXIMUM_CARDINALITY
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: IS_SELF_REF COLUMN_NAME: IS_SELF_REFERENCING
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: ID_GENERATION COLUMN_NAME: IDENTITY_GENERATION
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: ID_START COLUMN_NAME: IDENTITY_START
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: ID_INCREMENT COLUMN_NAME: IDENTITY_INCREMENT
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: ID_MAXIMUM COLUMN_NAME: IDENTITY_MAXIMUM
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: ID_MINIMUM COLUMN_NAME: IDENTITY_MINIMUM
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: ID_CYCLE COLUMN_NAME: IDENTITY_CYCLE
-- TABLE_NAME: COLUMNS_S COLUMN_NAME: GENERATION_EXPR COLUMN_NAME: GENERATION_EXPRESSION
-- TABLE_NAME: KEY_COLUMN_USAGE_S COLUMN_NAME: POSITION_IN_UC COLUMN_NAME: POSITION_IN_UNIQUE_CONSTRAINT
-- TABLE_NAME: REF_CONSTRAINTS COLUMN_NAME: UNIQUE_CONSTR_CAT COLUMN_NAME: UNIQUE_CONSTRAINT_CATALOG
-- TABLE_NAME: REF_CONSTRAINTS COLUMN_NAME: UNIQUE_CONSTR_SCH COLUMN_NAME: UNIQUE_CONSTRAINT_SCHEMA
-- TABLE_NAME: REF_CONSTRAINTS COLUMN_NAME: UNIQUE_CONSTR_NAME COLUMN_NAME: UNIQUE_CONSTRAINT_NAME
-- TABLE_NAME: TABLES_S COLUMN_NAME: SELF_REF_COL_NAME COLUMN_NAME: SELF_REFERENCING_COLUMN_NAME
-- TABLE_NAME: TABLES_S COLUMN_NAME: REF_GENERATION COLUMN_NAME: REFERENCE_GENERATION
-- TABLE_NAME: TABLES_S COLUMN_NAME: UDT_CATALOG COLUMN_NAME: USER_DEFINED_TYPE_CATALOG
-- TABLE_NAME: TABLES_S COLUMN_NAME: UDT_SCHEMA COLUMN_NAME: USER_DEFINED_TYPE_SCHEMA
-- TABLE_NAME: TABLES_S COLUMN_NAME: UDT_NAME COLUMN_NAME: USER_DEFINED_TYPE_NAME

-- # The other columns have the same names, and every column has the same type.
SELECT COUNT(*), SUM(CASE WHEN s.data_type = l.data_type AND s.is_nullable = l.is_nullable AND COALESCE(s.character_maximum_length, 0) = COALESCE(l.character_maximum_length, 0) THEN 1 ELSE 0 END)
FROM information_schema.columns AS s
JOIN information_schema.columns AS l ON l.ordinal_position = s.ordinal_position AND l.table_name = CASE s.table_name WHEN 'TABLES_S' THEN 'TABLES' WHEN 'COLUMNS_S' THEN 'COLUMNS' WHEN 'KEY_COLUMN_USAGE_S' THEN 'KEY_COLUMN_USAGE' WHEN 'REF_CONSTRAINTS' THEN 'REFERENTIAL_CONSTRAINTS' END;
-- COL1: 74 COL2: 74

-- # The short name views are views of the INFORMATION_SCHEMA too, so they can't
-- # be changed.
DELETE FROM information_schema.tables_s;
-- error 42501: insufficient privilege: INFORMATION_SCHEMA is read-only
